function stop(message) {
  console.error("\nSTOP: " + message + "\nNothing was changed.");
  process.exit(1);
}

// ---------- make sure this is the right folder and the earlier fixes are in ----------
if (!fs.existsSync("package.json") || !fs.readFileSync("package.json", "utf8").includes("laptop-price-tracker")) {
  stop("Run this from your laptop-core project folder (the one with package.json).");
}
if (!fs.existsSync("lib/supabase.ts") || !fs.readFileSync("lib/supabase.ts", "utf8").includes("fetchLaptopsPage")) {
  stop("lib\\supabase.ts is still the old version. Finish the earlier lag fix first, then run this again.");
}
const detailPath = "app/laptop/[id]/LaptopDetailClient.tsx";
if (!fs.existsSync(detailPath) || fs.readFileSync(detailPath, "utf8").split("\n").length < 500) {
  stop("app\\laptop\\[id]\\LaptopDetailClient.tsx looks wrong (it should be about 618 lines). Restore it first: git checkout 3b42124 -- ':(literal)app/laptop/[id]/LaptopDetailClient.tsx'");
}

const trackerPath = "components/TrackerClient.tsx";
const trackerSrc = fs.existsSync(trackerPath) ? fs.readFileSync(trackerPath, "utf8") : "";
if (!trackerSrc.includes("fetchLaptopsPage") && !trackerSrc.includes("fetchLaptopsSmart")) {
  stop("components\\TrackerClient.tsx isn't the version this installer expects. Finish the earlier lag fix first, then run this again.");
}

// ---------- new and replaced files ----------
console.log("Writing files:");
for (const [rel, b64] of Object.entries(FILES)) {
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  fs.writeFileSync(rel, Buffer.from(b64, "base64"));
  console.log("  wrote   " + rel);
}

// ---------- small edits to existing files ----------
function patch(rel, edit) {
  if (!fs.existsSync(rel)) stop(rel + " was not found.");
  const before = fs.readFileSync(rel, "utf8");
  let after;
  try {
    after = edit(before);
  } catch (e) {
    stop("Could not edit " + rel + ": " + e.message);
  }
  if (after === null) {
    console.log("  already " + rel);
    return;
  }
  fs.writeFileSync(rel, after, "utf8");
  console.log("  edited  " + rel);
}

console.log("\nEditing existing files:");

patch("app/layout.tsx", (src) => {
  if (src.includes("OfflineSupport")) return null;
  const nl = src.includes("\r\n") ? "\r\n" : "\n";
  const importRe = /import BackToTop from ['"]@\/components\/BackToTop['"];?/;
  if (!importRe.test(src)) throw new Error("could not find the BackToTop import");
  const analyticsRe = /^([ \t]*)<Analytics \/>/m;
  if (!analyticsRe.test(src)) throw new Error("could not find <Analytics />");
  return src
    .replace(importRe, (m) => m + nl + "import OfflineSupport from '@/components/OfflineSupport';")
    .replace(analyticsRe, (m, indent) => indent + "<OfflineSupport />" + nl + m);
});

patch("components/Sidebar.tsx", (src) => {
  if (src.includes('"todays-picks"')) return null;
  const nl = src.includes("\r\n") ? "\r\n" : "\n";
  const match = src.match(/\{\s*key: "best-picks",/);
  if (!match) throw new Error('could not find the "best-picks" item');
  const lineStart = src.lastIndexOf("\n", match.index) + 1;
  const indent = src.slice(lineStart, match.index);
  const item = [
    "{",
    '  key: "todays-picks",',
    '  label: "Today\'s Picks",',
    '  href: "/todays-picks",',
    "  icon: (",
    '    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">',
    '      <circle cx="12" cy="12" r="4" />',
    '      <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />',
    "    </svg>",
    "  ),",
    "},",
  ].join(nl + indent);
  return src.slice(0, match.index) + item + nl + indent + src.slice(match.index);
});

patch("app/sitemap.ts", (src) => {
  if (src.includes("todays-picks")) return null;
  const at = src.indexOf("/tracker`");
  if (at === -1) throw new Error("could not find the /tracker line");
  const lineStart = src.lastIndexOf("\n", at) + 1;
  const lineEnd = src.indexOf("\n", at);
  const raw = src.slice(lineStart, lineEnd);
  const cr = raw.endsWith("\r") ? "\r" : "";
  const copy = raw.replace(/\r$/, "").replace("/tracker`", "/todays-picks`").replace(/priority: [0-9.]+/, "priority: 0.8");
  return src.slice(0, lineEnd + 1) + copy + cr + "\n" + src.slice(lineEnd + 1);
});

patch("lib/supabase.ts", (src) => {
  if (/export const LAPTOP_SELECT/.test(src) && /export function shapeLaptop/.test(src)) return null;
  if (!/\nconst LAPTOP_SELECT =/.test(src) || !/\nfunction shapeLaptop\(/.test(src)) throw new Error("could not find LAPTOP_SELECT / shapeLaptop");
  return src.replace(/\nconst LAPTOP_SELECT =/, "\nexport const LAPTOP_SELECT =").replace(/\nfunction shapeLaptop\(/, "\nexport function shapeLaptop(");
});

// Daily refresh of the smart filter data (does not need Best Buy, so it works on Vercel)
{
  const rel = "vercel.json";
  const entry = { path: "/api/enrich-laptops", schedule: "30 9 * * *" };
  try {
    const text = fs.existsSync(rel) ? fs.readFileSync(rel, "utf8") : "{}";
    const bom = text.charCodeAt(0) === 0xfeff ? "\ufeff" : "";
    const json = JSON.parse(text.replace(/^\ufeff/, "") || "{}");
    json.crons = Array.isArray(json.crons) ? json.crons : [];
    if (json.crons.some((c) => c && c.path === entry.path)) {
      console.log("  already " + rel);
    } else {
      json.crons.push(entry);
      fs.writeFileSync(rel, bom + JSON.stringify(json, null, 2) + "\n", "utf8");
      console.log("  edited  " + rel);
    }
  } catch (e) {
    console.log("  SKIPPED " + rel + " (" + e.message + "). Add this to its crons list by hand: " + JSON.stringify(entry));
  }
}

